using Microsoft.Data.Sqlite;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.DependencyInjection;
namespace DrillingOperations.Tests;
[TestFixture,NonParallelizable]
public sealed class SurveyTruthTests
{
 [Test] public void Survey_IsDeterministic_PsdGrowing_AndSupportsUpwardTvd(){DrilledPathStation[] p=[new(0,100,1000,2000),new(300,100,1300,2000),new(600,60,1600,2100)];var o=new SurveyObservationOptions{StationSpacingM=30,RandomWalkStdDevM=.04,NoiseStdDevM=.05};var a=DeterministicSurveyModel.Generate("11111111-1111-4111-8111-111111111111",p,o);var replay=DeterministicSurveyModel.Generate("11111111-1111-4111-8111-111111111111",p,o);var otherRun=DeterministicSurveyModel.Generate("55555555-5555-4555-8555-555555555555",p,o);var changed=DeterministicSurveyModel.Generate("11111111-1111-4111-8111-111111111111",p,new(){StationSpacingM=30,RandomWalkStdDevM=.04,NoiseStdDevM=.05,CalibrationVersion="other"});Assert.Multiple(()=>{Assert.That(CanonicalJson.Serialize(a),Is.EqualTo(CanonicalJson.Serialize(replay)));Assert.That(CanonicalJson.Serialize(a),Is.Not.EqualTo(CanonicalJson.Serialize(changed)));Assert.That(CanonicalJson.Serialize(a),Is.Not.EqualTo(CanonicalJson.Serialize(otherRun)));Assert.That(a.Count,Is.EqualTo(21));Assert.That(a.Select(x=>x.ObservedTrueVerticalDepthM),Has.All.GreaterThanOrEqualTo(0));Assert.That(a.Zip(a.Skip(1),(x,y)=>y.MeasuredDepthM>x.MeasuredDepthM),Has.All.True);Assert.That(a.Select(x=>x.Covariance.EastEast),Is.Ordered.Ascending);Assert.That(a.All(x=>x.Covariance.EastEast>=0&&x.Covariance.NorthNorth>=0&&x.Covariance.TvdTvd>=0&&x.Covariance.EastNorth==x.Covariance.NorthEast),Is.True);});}
 [Test] public void Survey_BiasAndScale_AreExplicit_WhenNoiseDisabled(){DrilledPathStation[] p=[new(0,20,100,200),new(100,10,200,400)];var o=new SurveyObservationOptions{StationSpacingM=100,EastBiasM=3,NorthBiasM=-2,TvdBiasM=1,ScaleFactor=1.01,RandomWalkStdDevM=0,NoiseStdDevM=0};var x=DeterministicSurveyModel.Generate("run",p,o);Assert.Multiple(()=>{Assert.That(x[0].ObservedEastingM,Is.EqualTo(103));Assert.That(x[0].ObservedNorthingM,Is.EqualTo(198));Assert.That(x[1].ObservedEastingM,Is.EqualTo(204));Assert.That(x[1].ObservedNorthingM,Is.EqualTo(400));Assert.That(x[1].ObservedTrueVerticalDepthM,Is.EqualTo(10.9).Within(1e-10));});}
 [Test] public void SurveyOptions_EnforceSpacingAndCap(){Assert.Throws<Microsoft.Extensions.Options.OptionsValidationException>(()=>new SurveyObservationOptions{StationSpacingM=.9}.Validate());DrilledPathStation[] p=[new(0,0,0,0),new(10001,0,10001,0)];Assert.Throws<RunStageFailureException>(()=>DeterministicSurveyModel.Generate("run",p,new(){StationSpacingM=1}));}
 [Test] public async Task Survey_Persists_Restarts_IsExactlyOnce_AndImmutable(){await using var f=new StoreFixture();await f.InitializeAsync();RunResponse run=await StoreFixture.BindAndCreateAsync(f.Store);await f.Store.CompleteS0Async(run.RunId);await f.Store.MaterializePlanAsync(run.RunId,TestData.ScenarioSnapshot(),TestData.PredictionSnapshot());await f.Store.ExecuteDeterministicDrillingAsync(run.RunId,new());Assert.That(await f.Store.GenerateSurveyAsync(run.RunId,new()),Is.True);SurveyArtifact a=(await f.Store.GetSurveyArtifactAsync(run.RunId))!;var restarted=new DrillingOperationsStore(f.ConnectionString,TimeProvider.System);await restarted.InitializeAsync();Assert.That(CanonicalJson.Serialize(await restarted.GetSurveyArtifactAsync(run.RunId)),Is.EqualTo(CanonicalJson.Serialize(a)));Assert.That(await restarted.GenerateSurveyAsync(run.RunId,new()),Is.False);await using var c=new SqliteConnection(f.ConnectionString);await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="UPDATE SurveyArtifacts SET SurveyPathJson=$value WHERE RunId=$run";q.Parameters.AddWithValue("$value","[]");q.Parameters.AddWithValue("$run",run.RunId);Assert.ThrowsAsync<SqliteException>(async()=>await q.ExecuteNonQueryAsync());}
}

[TestFixture]
public sealed class ReservoirSamplingClientTests
{
 [TestCase("identity","StageADataMismatch",409)][TestCase("count","StageADataMismatch",409)][TestCase("property","StageADataMismatch",409)][TestCase("saturation","StageADataMismatch",409)][TestCase("coordinates","StageADataMismatch",409)][TestCase("porosity","StageADataMismatch",409)][TestCase("ntg","StageADataMismatch",409)][TestCase("permeability","StageADataMismatch",409)][TestCase("pressure","StageADataMismatch",409)][TestCase("interval","StageADataMismatch",409)][TestCase("tvd","StageADataMismatch",409)][TestCase("hash","StageADataMismatch",409)][TestCase("malformed","StageAMalformedResponse",409)][TestCase("unavailable","StageAUnavailable",502)]
 public void StageAResponses_FailClosed(string mode,string code,int status)
 {
  Guid scenario=Guid.Parse(TestData.ScenarioId),run=Guid.Parse("55555555-5555-4555-8555-555555555555");var path=new[]{new DrilledPathStation(0,0,0,0),new DrilledPathStation(100,100,100,0)};string canonical=JsonSerializer.Serialize(new{worldId="world-opaque-17",scenarioId=scenario,runId=run,pathKind=1,approvedSealedPredictionSha256=TestData.HashA,stations=path.Select(x=>new{x.MeasuredDepthM,x.EastingM,x.NorthingM,x.TrueVerticalDepthM})},new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase});string canonicalHash=DeterministicIdentity.Sha256(canonical),expectedBinding="rpb_"+DeterministicIdentity.Sha256("approved-path-binding-v1\n"+canonical);int calls=0;var handler=new DelegateHandler(_=>{calls++;if(mode=="unavailable")return TestData.Json(System.Net.HttpStatusCode.ServiceUnavailable,new{});if(mode=="malformed")return new(System.Net.HttpStatusCode.OK){Content=new StringContent("{")};if(calls==1)return TestData.Json(System.Net.HttpStatusCode.OK,new{bindingId=expectedBinding,worldId=mode=="identity"?"wrong":"world-opaque-17",scenarioId=scenario,runId=run,pathKind="AsDrilled",approvedSealedPredictionSha256=TestData.HashA,canonicalHash=mode=="hash"?canonicalHash.ToUpperInvariant():canonicalHash,stationCount=2});double oil=mode=="saturation"?1.2:.7,e=mode=="coordinates"?99:0,phi=mode=="porosity"?1.2:.2,ntg=mode=="ntg"?1.2:.8,perm=mode=="permeability"?0:1e-13,pressure=mode=="pressure"?0:1,top=(mode is "interval" or "tvd")?1:0,baseDepth=mode=="interval"?.5:2;return TestData.Json(System.Net.HttpStatusCode.OK,new{bindingId=expectedBinding,worldId="world-opaque-17",scenarioId=scenario,runId=run,propertySetVersion=mode=="property"?"wrong":"stage-b-truth-v1",sampleCount=mode=="count"?2:1,samples=new[]{new{measuredDepthM=0d,eastingM=e,northingM=0d,trueVerticalDepthM=0d,reservoirTopDepthM=top,reservoirBaseDepthM=baseDepth,porosity=phi,permeabilityM2=perm,netToGross=ntg,isReservoirQuality=true,pressurePa=pressure,oilSaturation=oil,waterSaturation=.3,gasSaturation=0d}}});});
  var client=new ReservoirSamplingClient(new HttpClient(handler){BaseAddress=new Uri("http://stage-a/")});var binding=new TruthBindingResponse("b",scenario.ToString("D"),TestData.HashA,TestData.HashB,"world-opaque-17","v","c",TestData.HashC,DateTimeOffset.UtcNow);var execution=new DrillingExecutionArtifact("e",run.ToString("D"),"p","m","o","h",path,[new(0,0),new(1,1)],0,1,"i","o",DateTimeOffset.UtcNow);StageASamplingException ex=Assert.ThrowsAsync<StageASamplingException>(async()=>await client.SampleAsync(binding,execution,new(),CancellationToken.None))!;Assert.Multiple(()=>{Assert.That(ex.DiagnosticCode,Is.EqualTo(code));Assert.That(ex.StatusCode,Is.EqualTo(status));});
 }
}

[TestFixture,NonParallelizable]
public sealed class TruthPersistenceTests
{
 [Test] public async Task TruthBatch_PersistsAcrossRestart_ExactlyOnce_Immutable_AndHidden(){await using var factory=new ApiFactory();using HttpClient client=factory.CreateInternalClient();using var bind=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/scenarios/{TestData.ScenarioId}/bind"){Content=JsonContent.Create(TestData.Binding())};bind.Headers.Add("Idempotency-Key","truth-bind");(await client.SendAsync(bind)).EnsureSuccessStatusCode();using var create=new HttpRequestMessage(HttpMethod.Post,"/drillingoperations/api/runs"){Content=JsonContent.Create(TestData.Run())};create.Headers.Add("Idempotency-Key","truth-run");HttpResponseMessage created=await client.SendAsync(create);RunResponse run=JsonSerializer.Deserialize<RunResponse>(await created.Content.ReadAsStringAsync(),CanonicalJson.SerializerOptions)!;RunResponse? current=null;for(int i=0;i<80;i++){current=await client.GetFromJsonAsync<RunResponse>($"/drillingoperations/api/runs/{run.RunId}",CanonicalJson.SerializerOptions);if(current?.CurrentStage==RunStageKind.S6DesignCompletion&&current.Status==RunStatus.AwaitingApproval)break;await Task.Delay(25);}var store=factory.Services.GetRequiredService<DrillingOperationsStore>();TruthSampleBatch batch=(await store.GetTruthSampleBatchAsync(run.RunId))!;Assert.That(batch,Is.Not.Null);LogObservationArtifact logs=(await store.GetLogObservationBatchAsync(run.RunId))!;Assert.That(logs,Is.Not.Null);var restarted=new DrillingOperationsStore($"Data Source={factory.DatabasePath}",TimeProvider.System);await restarted.InitializeAsync();Assert.That(CanonicalJson.Serialize(await restarted.GetTruthSampleBatchAsync(run.RunId)),Is.EqualTo(CanonicalJson.Serialize(batch)));Assert.That(CanonicalJson.Serialize(await restarted.GetLogObservationBatchAsync(run.RunId)),Is.EqualTo(CanonicalJson.Serialize(logs)));Assert.That(await restarted.GenerateLogsAsync(run.RunId,new()),Is.False);string runApi=await client.GetStringAsync($"/drillingoperations/api/runs/{run.RunId}");string audit=await client.GetStringAsync($"/drillingoperations/api/audit?scenarioId={TestData.ScenarioId}");Assert.Multiple(()=>{Assert.That(runApi,Does.Not.Contain("oilSaturation"));Assert.That(audit,Does.Not.Contain("oilSaturation"));Assert.That(audit,Does.Not.Contain("eastingM"));Assert.That(runApi,Does.Not.Contain("grApi"));Assert.That(audit,Does.Not.Contain("pressurePa"));});await using var c=new SqliteConnection($"Data Source={factory.DatabasePath}");await c.OpenAsync();await using var logMutation=c.CreateCommand();logMutation.CommandText="UPDATE ObservationBatches SET OutputHash=$hash WHERE RunId=$run";logMutation.Parameters.AddWithValue("$hash",TestData.HashA);logMutation.Parameters.AddWithValue("$run",run.RunId);Assert.ThrowsAsync<SqliteException>(async()=>await logMutation.ExecuteNonQueryAsync());await using var logTamper=c.CreateCommand();logTamper.CommandText="DROP TRIGGER TR_ObservationBatches_NoUpdate;UPDATE ObservationBatches SET OutputHash=$hash WHERE RunId=$run";logTamper.Parameters.AddWithValue("$hash",TestData.HashA);logTamper.Parameters.AddWithValue("$run",run.RunId);await logTamper.ExecuteNonQueryAsync();Assert.ThrowsAsync<PersistenceIntegrityException>(async()=>await restarted.GetLogObservationBatchAsync(run.RunId));await using var q=c.CreateCommand();q.CommandText="UPDATE TruthSampleBatches SET ResponseHash=$hash WHERE RunId=$run";q.Parameters.AddWithValue("$hash",TestData.HashA);q.Parameters.AddWithValue("$run",run.RunId);Assert.ThrowsAsync<SqliteException>(async()=>await q.ExecuteNonQueryAsync());await using var tamper=c.CreateCommand();tamper.CommandText="DROP TRIGGER TR_TruthSampleBatches_NoUpdate;UPDATE TruthSampleBatches SET ResponseHash=$hash WHERE RunId=$run";tamper.Parameters.AddWithValue("$hash",TestData.HashA);tamper.Parameters.AddWithValue("$run",run.RunId);await tamper.ExecuteNonQueryAsync();Assert.ThrowsAsync<PersistenceIntegrityException>(async()=>await restarted.GetTruthSampleBatchAsync(run.RunId));}
}









